let.codeExample:
if (true) {
  let x = 5;
  console.log(x); // 5
}
// console.log(x); // ReferenceError

const.codeExample:
const user = { name: 'Fran' };
user.name = 'Frank'; // Válido (mutación)
// user = {}; // Error (reasignación)

boolean.codeExample:
if (isValid) {
  // hace algo
} else {
  // no hace nada
}

null.codeExample:
function getUser() {
  return null; // Usuario no encontrado intencionalmente
}

undefined.codeExample:
let x;
console.log(x); // undefined
function test() {}
console.log(test()); // undefined

instanceof.codeExample:
class Car {}
const myCar = new Car();
console.log(myCar instanceof Car); // true

JSON.codeExample:
const data = { id: 1 };
const str = JSON.stringify(data);
// '{"id":1}'

function.codeExample:
function sumar(a, b) {
  return a + b;
}
console.log(sumar(2, 3));

this.codeExample:
const obj = {
  name: 'Yo',
  greet() {
    return this.name;
  }
};

bind.codeExample:
const user = { name: 'Alex' };
function say() { console.log(this.name); }
const sayAlex = say.bind(user);
sayAlex(); // 'Alex'

call.codeExample:
function greet(lang) {
  console.log(`${lang}: ${this.name}`);
}
const user = { name: 'Bob' };
greet.call(user, 'ES'); // 'ES: Bob'

destructuring.codeExample:
const user = { id: 1, info: { name: 'F' } };
const { info: { name } } = user;
console.log(name); // 'F'

nullish.codeExample:
const count = 0;
const qty = count || 10; // 10 (¡mal! 0 es válido)
const realQty = count ?? 10; // 0 (¡bien!)

class.codeExample:
class Rect {
  constructor(h, w) { this.h = h; this.w = w; }
  area() { return this.h * this.w; }
}

extends.codeExample:
class Animal {
  move() { console.log('moving'); }
}
class Dog extends Animal {
  bark() { console.log('woof'); }
}

prototype.codeExample:
function Cat() {}
Cat.prototype.meow = function() { console.log('Miau'); };
const michi = new Cat();
michi.meow();

rest.codeExample:
function sum(...args) {
  return args.reduce((a, b) => a + b, 0);
}

map.codeExample:
const nums = [1, 2, 3];
const squares = nums.map(x => x * x);
// [1, 4, 9]

filter.codeExample:
const nums = [1, 2, 3, 4];
const evens = nums.filter(n => n % 2 === 0);
// [2, 4]

for.codeExample:
for (let i = 0; i < 5; i++) {
  if (i === 3) break;
  console.log(i);
}

for...of.codeExample:
const colors = ['red', 'blue'];
for (const c of colors) {
  console.log(c);
}

Promise.codeExample:
const miPromesa = new Promise((resolve, reject) => {
  setTimeout(() => resolve('Hecho!'), 1000);
});

await.codeExample:
async function main() {
  const data = await fetch('/api');
  console.log(data);
}

export.codeExample:
// file.js
export const add = (a,b) => a+b;
export default function main() {}

default.codeExample:
// user.js
export default class User { ... }
// main.js
import Persona from './user';

generator.codeExample:
function* count() { yield 1; yield 2; }
const it = count();
console.log(it.next().value); // 1

yield.codeExample:
function* echo() {
  const input = yield 'Dime algo';
  console.log(input);
}

Symbol.codeExample:
const id = Symbol('id');
const obj = { [id]: 123 };
console.log(obj[id]); // 123

Proxy.codeExample:
const handler = { get: () => '404' };
const p = new Proxy({}, handler);
console.log(p.foo); // '404'

try.codeExample:
try {
  throw new Error('Oops');
} catch (e) {
  console.log(e.message);
}
